function getBatchSize(zoom) {
  if (zoom <= 7) return 250;  // Very large batches for zoomed-out views
  if (zoom <= 9) return 150;  // Medium batches for mid-range zoom
  return 100;                 // Standard batches for zoomed-in views
}

// Cancel any pending batch flush (call when stream ends or view changes)
function cancelPendingFlush() {
  if (batchFlushRAFId) {
