async function streamMarkersWithMsgpack(url, handlers) {
  const { onMarker, onComplete, onError } = handlers;

  try {
    const response = await fetch(url + '&format=msgpack');
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const reader = response.body.getReader();
    let buffer = new Uint8Array(0);

    const processChunk = async () => {
      const { done, value } = await reader.read();

      if (done) {
        onComplete();
        return;
      }

      // Append to buffer
      const newBuffer = new Uint8Array(buffer.length + value.length);
      newBuffer.set(buffer);
      newBuffer.set(value, buffer.length);
      buffer = newBuffer;

      // Process complete frames (4-byte length prefix + data)
      while (buffer.length >= 4) {
        const frameLen = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];

        if (frameLen === 0) {
          // End marker - zero length frame
          onComplete();
          return;
        }

        if (buffer.length < 4 + frameLen) break; // Wait for more data

        const frameData = buffer.slice(4, 4 + frameLen);
        buffer = buffer.slice(4 + frameLen);

        // Send to worker for decoding
        if (markerWorker) {
          markerWorker.postMessage({
            type: 'parse',
            data: frameData.buffer,
            format: 'msgpack',
            streamId: workerStreamId
          }, [frameData.buffer]); // Transfer ownership for zero-copy
        }
      }

      // Continue reading
      processChunk();
    };

    processChunk();
  } catch (err) {
    console.error('[Msgpack] Stream error:', err);
    onError(err);
  }
}

// Check if browser supports ReadableStream (required for msgpack)
const supportsReadableStream = typeof ReadableStream !== 'undefined' &&
                               typeof fetch !== 'undefined';

if (useMsgpackStreaming) {
