		var sampledSrc <-chan database.Marker
		if sampleRate < 1.0 {
			sampledSrc = sampleMarkerChannel(ctx, baseSrc, sampleRate)
		} else {
			sampledSrc = baseSrc
		}

		// Aggregate and collect all markers before streaming
		agg := aggregateMarkers(ctx, sampledSrc, nil, zoom)

		// Collect all aggregated markers into a slice
		aggregatedMarkers = make([]database.Marker, 0, 10000)
		for m := range agg {
			aggregatedMarkers = append(aggregatedMarkers, m)
		}

		// Check for errors from the database query
		if err := <-errCh; err != nil {
			log.Printf("Error streaming markers: %v", err)
			http.Error(w, "Error streaming markers", http.StatusInternalServerError)
			return
		}

		// Cache the aggregated result if reasonable size (avoid caching huge track views)
		if len(aggregatedMarkers) < 50000 {
			tileCacheMu.Lock()
			tileCache.Add(cacheKey, aggregatedMarkers)
			tileCacheMu.Unlock()
			log.Printf("[Cache ADD] Cached %d markers for future requests", len(aggregatedMarkers))
		} else {
			log.Printf("[Cache SKIP] Result too large (%d markers), not caching", len(aggregatedMarkers))
		}
	}

	// Now stream the aggregated markers (either from cache or freshly computed)
	agg := make(chan database.Marker, len(aggregatedMarkers))
	go func() {
		defer close(agg)
		for _, m := range aggregatedMarkers {
			agg <- m
		}
	}()

