	flusher.Flush()

	for {
		select {
		case <-ctx.Done():
			return
		case err, ok := <-errCh:
			if !ok {
				errCh = nil
				continue
			}
			if err != nil {
				if useMsgpack {
					// Send zero-length frame as error indicator
					w.Write([]byte{0, 0, 0, 0})
				} else {
					fmt.Fprintf(w, "event: done\ndata: %v\n\n", err)
				}
				flusher.Flush()
				return
			}
			errCh = nil
		case m, ok := <-agg:
			if !ok {
				if useMsgpack {
					// Send zero-length frame as end marker
					w.Write([]byte{0, 0, 0, 0})
				} else {
					fmt.Fprint(w, "event: done\ndata: end\n\n")
				}
				flusher.Flush()
				return
			}
			if useMsgpack {
				b, _ := msgpack.Marshal(m)
				writeMsgpackFrame(b)
			} else {
				b, _ := json.Marshal(m)
				fmt.Fprintf(w, "data: %s\n\n", b)
			}
			flusher.Flush()
		}
	}
}

