			}
		} else {
			// Parallel processing for large datasets
			var wg sync.WaitGroup
			batchSize := (len(uploads) + numWorkers - 1) / numWorkers

			for w := 0; w < numWorkers; w++ {
				wg.Add(1)
				start := w * batchSize
				end := start + batchSize
				if end > len(uploads) {
					end = len(uploads)
