// indexExistsPortable checks index presence using portable catalog queries.
// We keep it engine-specific but simple, and do this at app level (= not
// relying on engine-specific CREATE options).
func (db *Database) indexExistsPortable(ctx context.Context, dbType, indexName string) (bool, error) {
	switch strings.ToLower(dbType) {
	case "pgx":
		// Look for an index with this name in any schema on search_path.
		// pg_class.relkind = 'i' means "index".
		const q = `
SELECT 1
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind = 'i'
  AND c.relname = $1
  AND n.nspname = ANY (current_schemas(true))
LIMIT 1`
		var one int
		err := db.DB.QueryRowContext(ctx, q, indexName).Scan(&one)
		if err == sql.ErrNoRows {
			return false, nil
		}
		return err == nil, err

	case "sqlite", "chai":
		// Standard SQLite catalog
		const q = `SELECT name FROM sqlite_master WHERE type='index' AND name=? LIMIT 1`
		var name string
		err := db.DB.QueryRowContext(ctx, q, indexName).Scan(&name)
		if err == sql.ErrNoRows {
			return false, nil
		}
		return err == nil, err

	default:
		// Unknown engine: assume not exists to try creation;
		// caller will catch "already exists" text if any.
		return false, nil
	}
}

// InitSchema creates minimal required schema synchronously so that
// the app can accept traffic immediately. Heavy indexes are built later
// by EnsureIndexesAsync in background.
func (db *Database) InitSchema(cfg Config) error {
	var (
		schema     string
		statements []string
	)

	switch strings.ToLower(cfg.DBType) {
	case "pgx":
		// PostgreSQL — standard types, named UNIQUE to target by ON CONFLICT
		schema = `
CREATE TABLE IF NOT EXISTS markers (
  id          BIGSERIAL PRIMARY KEY,
  doseRate    DOUBLE PRECISION,
  date        BIGINT,
  lon         DOUBLE PRECISION,
  lat         DOUBLE PRECISION,
  countRate   DOUBLE PRECISION,
  zoom        INTEGER,
  speed       DOUBLE PRECISION,
  trackID     TEXT,
  altitude    DOUBLE PRECISION,
  detector    TEXT,
  radiation   TEXT,
  temperature DOUBLE PRECISION,
  humidity    DOUBLE PRECISION,
  device_id   TEXT,
  transport   TEXT,
  device_name TEXT,
  tube        TEXT,
  country     TEXT,
  has_spectrum BOOLEAN DEFAULT FALSE,
  geom        GEOMETRY(POINT, 4326),
  CONSTRAINT markers_unique UNIQUE (doseRate,date,lon,lat,countRate,zoom,speed,trackID)
);

-- Create PostGIS spatial index for optimal spatial query performance
-- Use composite (zoom, geom) index for better performance with zoom-filtered queries
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE INDEX IF NOT EXISTS idx_markers_zoom_geom_gist ON markers USING GIST(zoom, geom);

-- Create function to automatically update geom column when lat/lon changes
CREATE OR REPLACE FUNCTION update_marker_geom()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.lat IS NOT NULL AND NEW.lon IS NOT NULL THEN
    NEW.geom := ST_SetSRID(ST_MakePoint(NEW.lon, NEW.lat), 4326);
  ELSE
    NEW.geom := NULL;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create trigger to automatically populate geom column
DROP TRIGGER IF EXISTS trigger_update_marker_geom ON markers;
CREATE TRIGGER trigger_update_marker_geom
  BEFORE INSERT OR UPDATE OF lat, lon ON markers
  FOR EACH ROW
  EXECUTE FUNCTION update_marker_geom();

