-- Populate zoom levels 1-10 for hybrid approach
-- Strategy:
--   Zoom 1-10: Pre-computed clusters (fast queries, few markers)
--   Zoom 11+: Query zoom=0 markers directly (spatial filter makes it fast)
--
-- At high zoom (11+), viewport is small (~1-10 km²) so spatial index
-- efficiently filters 133M markers to just thousands in the viewport.

-- Add marker_count column
ALTER TABLE markers ADD COLUMN IF NOT EXISTS marker_count INTEGER DEFAULT 1;

-- Function to populate all zoom levels at once
CREATE OR REPLACE FUNCTION populate_all_zoom_levels()
RETURNS TABLE (zoom_level INTEGER, clusters INTEGER, seconds NUMERIC) AS $$
DECLARE
    start_time TIMESTAMP;
    end_time TIMESTAMP;
    grid_degrees DOUBLE PRECISION;
    rows_inserted BIGINT;
    z INTEGER;
BEGIN
    -- Loop through zoom levels 1-10
    FOR z IN 1..10 LOOP
        start_time := clock_timestamp();
        grid_degrees := 360.0 / POWER(2, z + 1);

        RAISE NOTICE 'Creating zoom % clusters (%.3f° grid = %.1f km)...',
            z, grid_degrees, grid_degrees * 111;

        -- Insert aggregated markers for this zoom level
        INSERT INTO markers (
            doseRate, date, lon, lat, countRate, zoom, speed, trackID, geom,
            has_spectrum, marker_count, temperature, humidity
        )
        SELECT
            AVG(doseRate),
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY date)::BIGINT,
            (FLOOR(lon / grid_degrees) + 0.5) * grid_degrees,
            (FLOOR(lat / grid_degrees) + 0.5) * grid_degrees,
            AVG(countRate),
            z,
            AVG(COALESCE(speed, 0)),
            'z' || z || '_' || FLOOR(lon / grid_degrees)::TEXT || '_' || FLOOR(lat / grid_degrees)::TEXT,
            ST_SetSRID(ST_MakePoint(
                (FLOOR(lon / grid_degrees) + 0.5) * grid_degrees,
                (FLOOR(lat / grid_degrees) + 0.5) * grid_degrees
            ), 4326),
            BOOL_OR(COALESCE(has_spectrum, FALSE)),
            COUNT(*)::INTEGER,
            AVG(COALESCE(temperature, 0)),
            AVG(COALESCE(humidity, 0))
        FROM markers
        WHERE zoom = 0
        GROUP BY FLOOR(lon / grid_degrees), FLOOR(lat / grid_degrees);

        GET DIAGNOSTICS rows_inserted = ROW_COUNT;
        end_time := clock_timestamp();

        RAISE NOTICE 'Zoom %: Created % clusters in % seconds',
            z, rows_inserted, EXTRACT(EPOCH FROM (end_time - start_time));

        zoom_level := z;
        clusters := rows_inserted;
        seconds := EXTRACT(EPOCH FROM (end_time - start_time));
        RETURN NEXT;
    END LOOP;

    -- Create index on zoom column if it doesn't exist
    IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'idx_markers_zoom') THEN
        RAISE NOTICE 'Creating index on zoom column...';
        CREATE INDEX idx_markers_zoom ON markers(zoom);
    END IF;

    RAISE NOTICE 'All zoom levels created! Running ANALYZE...';
    ANALYZE markers;
    RAISE NOTICE 'Complete!';
END;
$$ LANGUAGE plpgsql;

-- Usage:
-- SELECT * FROM populate_all_zoom_levels();
--
-- Expected results:
-- Zoom 1-5: < 100 clusters each (very coarse)
-- Zoom 6-7: hundreds of clusters
-- Zoom 8-9: thousands of clusters
-- Zoom 10: tens of thousands of clusters
--
-- Total time: ~30-60 minutes for all zoom levels
-- Disk space: ~2-3 GB additional (small compared to 133M zoom=0 markers)

