	}

	// Calculate total pages
	totalPages := (totalCount + limit - 1) / limit
	if totalPages < 1 {
		totalPages = 1
	}

	// Fetch current page of uploads
	uploads, err := db.GetUploadsPaginated(ctx, limit, offset, userID, search)
