			--border-color: #444;
			--link-color: #90caf9;
			--shadow: 0 1px 3px rgba(255,255,255,0.1);
			--th-bg: #616161;
			--hover-bg: #333;
			--badge-bg: rgba(144, 202, 249, 0.2);
			--badge-text: #90caf9;
